+
+    if (msg.keys & KEY_UP || msg.keys & KNOB_LEFT) {
+        if (ui_state->detail_scroll > 0) {
+            ui_state->detail_scroll -= scrollStep;
+            if (ui_state->detail_scroll < 0)
+                ui_state->detail_scroll = 0;

