+static_assert(sizeof(struct m17Packet) <= MSG_PKT_MAX_SIZE,
+              "M17 packets must fit in an inbox packet buffer");
+static_assert(sizeof(m17Packet::src) <= MSG_ADDR_MAX_LEN,
+              "M17 callsigns must fit in a message address");
