+    bk4819_gpio_pin_set(&c62_bk4819, GPIO_UHF_RX_LNA,
+                        false); // UHF RX LNA
+    bk4819_gpio_pin_set(&c62_bk4819, GPIO_VHF_TX_PA,
+                        false); // VHF TX PA
+    bk4819_gpio_pin_set(&c62_bk4819, GPIO_UHF_TX_PA,
+                        false); // UHF TX PA
+    bk4819_gpio_pin_set(&c62_bk4819, GPIO_ALC_TX_LED,
+                        false); // ALC / TX LED
+}
