+        bk4819_gpio_pin_set(&c62_bk4819, GPIO_VHF_RX_LNA,
+                            true); // VHF RX LNA
+    } else {
+        bk4819_gpio_pin_set(&c62_bk4819, GPIO_UHF_RX_LNA,
+                            true); // UHF RX LNA
+    }
