+/*
+ * Enable the controller ONCE and leave it enabled (target set while disabled,
+ * then wait for IC_ENABLE_STATUS to settle), mirroring the proven i2c_csky
+ * (I2C1) sequence on the same DesignWare core.  Toggling IC_ENABLE around every
+ * transfer -- and not waiting for it to settle -- corrupts the FIFO/command
+ * alignment and returns garbage (the original RTC round-trip failure).
+ */
+static void i2c2_setup(void)
+{
+    int spin;
+
+    I2C2->IC_ENABLE = 0u; /* IC_TAR can only change while off */
+    for (spin = I2C_SPIN_LIMIT; spin && (I2C2->IC_ENABLE_STATUS & 1u); --spin) {
+    }
+
+    I2C2->IC_CON = I2C_CON_MASTER_FS; /* master, 7-bit, FS, restart */
+    I2C2->IC_FS_SCL_HCNT = I2C_SCL_HCNT;
+    I2C2->IC_FS_SCL_LCNT = I2C_SCL_LCNT;
+    I2C2->IC_INTR_MASK = 0x40u;
+    I2C2->IC_RX_TL = 6u;
+    I2C2->IC_TX_TL = 6u;
+    I2C2->IC_TAR = RTC_I2C_SLAVE;
+
+    I2C2->IC_ENABLE = 1u; /* enable once, keep enabled */
+    for (spin = I2C_SPIN_LIMIT; spin && !(I2C2->IC_ENABLE_STATUS & 1u);
+         --spin) {
+    }
+}
+
+/* Post-transfer health check: a clean transfer leaves the TX FIFO empty, the
+ * bus idle and no abort latched.  Otherwise clear the abort and re-init. */
+static void i2c2_recover(void)
+{
+    if ((I2C2->IC_STATUS & I2C_STA_TFE) && !(I2C2->IC_STATUS & I2C_STA_ACTIVITY)
+        && (I2C2->IC_TX_ABRT_SRC == 0u))
+        return;
+    (void)I2C2->IC_CLR_TX_ABRT;
+    i2c2_setup();
+}
+
+static void rtc_reg_write(uint8_t reg, uint8_t val)
+{
+    int spin;
+
+    for (spin = I2C_SPIN_LIMIT; spin && !(I2C2->IC_STATUS & I2C_STA_TFNF);
+         --spin) {
+    }
+    I2C2->IC_DATA_CMD = reg;
+    for (spin = I2C_SPIN_LIMIT; spin && !(I2C2->IC_STATUS & I2C_STA_TFNF);
+         --spin) {
+    }
+    I2C2->IC_DATA_CMD = (uint32_t)val | I2C_CMD_STOP;
+
+    I2C2->IC_START = 1u; /* HR_C7000 explicit transfer trigger */
+    for (spin = I2C_SPIN_LIMIT; spin && !(I2C2->IC_STATUS & I2C_STA_TFE);
+         --spin) {
+    }
+    I2C2_WAIT_IDLE();
+    I2C2->IC_START = 0u;
+    i2c2_recover();
+}
+
+static uint8_t rtc_reg_read(uint8_t reg)
+{
+    int spin;
+    uint8_t val;
+
+    /* Combined repeated-START read: write the register pointer (no STOP),
+     * then a read command with STOP, all loaded before IC_START. */
+    for (spin = I2C_SPIN_LIMIT; spin && !(I2C2->IC_STATUS & I2C_STA_TFNF);
+         --spin) {
+    }
+    I2C2->IC_DATA_CMD = reg;
+    for (spin = I2C_SPIN_LIMIT; spin && !(I2C2->IC_STATUS & I2C_STA_TFNF);
+         --spin) {
+    }
+    I2C2->IC_DATA_CMD = I2C_CMD_READ | I2C_CMD_STOP;
+
+    I2C2->IC_START = 1u;
+    for (spin = I2C_SPIN_LIMIT; spin && !(I2C2->IC_STATUS & I2C_STA_RFNE);
+         --spin) {
+    }
+    val = (uint8_t)I2C2->IC_DATA_CMD;
+
+    I2C2_WAIT_IDLE();
+    I2C2->IC_START = 0u;
+    i2c2_recover();
+    return val;
+}
