+                             const void *data, const size_t len,
+                             const bool stop)
+{
+    I2C_TypeDef *hw = (I2C_TypeDef *)dev->periph;
+    const uint8_t *bytes = (const uint8_t *)data;
+
+    if ((hw == NULL) || ((len != 0u) && (bytes == NULL)))
+        return -1;
