+        hw->IC_DATA_CMD = cmd;
+    }
+
+    hw->IC_START = 1u;
+    for (size_t i = 0; i < len; ++i) {
+        wait_status(hw, I2C_STA_RFNE, true);
+        bytes[i] = (uint8_t)hw->IC_DATA_CMD;
+    }
+    wait_status(hw, I2C_STA_ACTIVITY, false);
+    hw->IC_START = 0u;
