+                                                 0xFF, 0xFF, 0xFF };
+static constexpr const char BROADCAST_CALL_STR[] = "ALL";
+
+static constexpr const call_t INVALID_CALL = { 0x00, 0x00, 0x00,
+                                               0x00, 0x00, 0x00 };
+static constexpr const char INVALID_CALL_STR[] = "INVALID";
+
+Callsign &getBroadcastCallsign()
